10 /*
11 Goal: Implement the well known merge sort algorithm in O(a.Length X log_2(a.Length)) time, recursively.
12 
13 - Divide the contents of the original array into two local arrays
14 - After sorting the local arrays (recursively), merge the contents of the two returned arrays using the Merge method (see below)
15 - DO NOT modify the specification or any other part of the method's signature
16 - DO NOT introduce any further methods
17 */
18 method MergeSort(a: array<int>) returns (b: array<int>)
19 	ensures b.Length == a.Length && Sorted(b[..]) && multiset(a[..]) == multiset(b[..])
20 	decreases a.Length
21 {
22 	if (a.Length <= 1) {b := a;}
23     else{
24         var mid: nat := a.Length / 2;
25         var a1: array<int> := new int[mid];
26         var a2: array<int> := new int[a.Length - mid];
27         assert a1.Length <= a2.Length;
28         assert a.Length == a1.Length + a2.Length;
29 
30         var i: nat := 0;
31         while (i < a1.Length )
32             invariant Inv(a[..], a1[..], a2[..], i, mid)
33             decreases a1.Length - i
34         {
35             a1[i] := a[i];
36             a2[i] := a[i+mid];
37             i:=i+1;
38         }
39         assert !(i < a1.Length);
40         assert (i >= a1.Length);
41         assert i == a1.Length;
42         assert Inv(a[..], a1[..], a2[..], i, mid);
43         assert (i <= |a1[..]|) && (i <= |a2[..]|) && (i+mid <= |a[..]|);
44         assert (a1[..i] == a[..i]) && (a2[..i] == a[mid..(i+mid)]);
45         
46         if(a1.Length < a2.Length) {
47             a2[i] := a[i+mid];
48             assert i+1 == a2.Length;
49             assert (a2[..i+1] == a[mid..(i+1+mid)]);
50             assert (a1[..i] == a[..i]) && (a2[..i+1] == a[mid..(i+1+mid)]);
51             assert a[..i] + a[i..i+1+mid] == a1[..i] + a2[..i+1];
52             assert a[..i] + a[i..i+1+mid] == a1[..] + a2[..];
53             assert a[..] == a1[..] + a2[..];
54         } // If a.Length is odd.
55         else{
56             assert i == a2.Length;
57             assert (a1[..i] == a[..i]) && (a2[..i] == a[mid..(i+mid)]);
58             assert a[..i] + a[i..i+mid] == a1[..i] + a2[..i];
59             assert a[..i] + a[i..i+mid] == a1[..] + a2[..];
60             assert a[..] == a1[..] + a2[..];
61         }
62 
63         assert a1.Length < a.Length;
64         a1:= MergeSort(a1);
65         assert a2.Length < a.Length;
66         a2:= MergeSort(a2);
67         b := new int [a.Length];
68         Merge(b, a1, a2);
69         assert multiset(b[..]) == multiset(a1[..]) + multiset(a2[..]);
70         assert Sorted(b[..]);        
71     }
72     assert b.Length == a.Length && Sorted(b[..]) && multiset(a[..]) == multiset(b[..]);
73 } 
