85 method Merge(b: array<int>, c: array<int>, d: array<int>)
86 	requires b != c && b != d && b.Length == c.Length + d.Length
87 	requires Sorted(c[..]) && Sorted(d[..])
88 	ensures Sorted(b[..]) && multiset(b[..]) == multiset(c[..])+multiset(d[..])
